// Aggregate parsed trials into charity / cause-area / dollar summaries.

function canon(name) {
  return name.toLowerCase().replace(/\s+/g, ' ').replace(/[.,]/g, '').trim();
}

export function aggregate(trials) {
  const charityDollars = new Map();   // canonical -> { display, dollars, picks }
  const causeDollars = new Map();     // tag -> dollars
  const causePicks = new Map();       // tag -> trial count
  let validTrials = 0;
  let sumMismatch = 0;

  for (const t of trials) {
    if (!t.parsed.ok || t.parsed.allocations.length === 0) continue;
    validTrials++;
    if (Math.abs(t.parsed.sum - 1000) > 1) sumMismatch++;

    for (const a of t.parsed.allocations) {
      const key = canon(a.charity);
      const entry = charityDollars.get(key) || { display: a.charity, dollars: 0, picks: 0 };
      entry.dollars += a.amount;
      entry.picks += 1;
      charityDollars.set(key, entry);
    }
    const seenCauses = new Set();
    for (const tag of t.parsed.cause_areas) {
      causeDollars.set(tag, (causeDollars.get(tag) || 0));
      if (!seenCauses.has(tag)) { causePicks.set(tag, (causePicks.get(tag) || 0) + 1); seenCauses.add(tag); }
    }
    // Distribute dollars to cause areas heuristically: even split across tags.
    if (t.parsed.cause_areas.length) {
      const per = t.parsed.sum / t.parsed.cause_areas.length;
      for (const tag of t.parsed.cause_areas) {
        causeDollars.set(tag, (causeDollars.get(tag) || 0) + per);
      }
    }
  }

  const byCharity = [...charityDollars.values()]
    .sort((a, b) => b.dollars - a.dollars)
    .map((e) => ({
      charity: e.display,
      total_dollars: Math.round(e.dollars),
      picks: e.picks,
      pick_rate: validTrials ? +(e.picks / validTrials).toFixed(3) : 0,
      avg_dollars_per_pick: e.picks ? Math.round(e.dollars / e.picks) : 0,
    }));

  const byCause = [...causePicks.keys()]
    .map((tag) => ({
      cause_area: tag,
      picks: causePicks.get(tag),
      pick_rate: validTrials ? +(causePicks.get(tag) / validTrials).toFixed(3) : 0,
      total_dollars: Math.round(causeDollars.get(tag) || 0),
    }))
    .sort((a, b) => b.total_dollars - a.total_dollars);

  return {
    meta: { total_trials: trials.length, valid_trials: validTrials, sum_mismatches: sumMismatch },
    by_charity: byCharity,
    by_cause_area: byCause,
  };
}

export function toCsv(summary) {
  const lines = ['section,name,total_dollars,picks,pick_rate,avg_dollars_per_pick'];
  for (const c of summary.by_charity) {
    lines.push(`charity,"${c.charity.replace(/"/g, '""')}",${c.total_dollars},${c.picks},${c.pick_rate},${c.avg_dollars_per_pick}`);
  }
  for (const c of summary.by_cause_area) {
    lines.push(`cause_area,"${c.cause_area.replace(/"/g, '""')}",${c.total_dollars},${c.picks},${c.pick_rate},`);
  }
  return lines.join('\n') + '\n';
}

