  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    const next = () => argv[++i];
    if (a === '--provider') args.provider = next();
    else if (a === '--trials') args.trials = parseInt(next(), 10);
    else if (a === '--model') args.model = next();
    else if (a === '--concurrency') args.concurrency = parseInt(next(), 10);
    else if (a === '--temperature') args.temperature = parseFloat(next());
    else if (a === '--out') args.outDir = next();
    else if (a === '--help' || a === '-h') { printHelp(); process.exit(0); }
  }
  return args;
