// Extract the structured allocation JSON from a model's free-text response.

export function parseAllocation(text) {
  const fenced = [...text.matchAll(/```json\s*([\s\S]*?)```/gi)];
  const candidates = [];
  if (fenced.length) candidates.push(fenced[fenced.length - 1][1]);
  // Fallback: last {...} block.
  const brace = text.lastIndexOf('{');
  if (brace !== -1) candidates.push(text.slice(brace));

  for (const raw of candidates) {
    try {
      const obj = JSON.parse(raw.trim());
      if (Array.isArray(obj.allocations)) return normalize(obj);
    } catch { /* try next candidate */ }
  }
  return { ok: false, allocations: [], cause_areas: [], sum: 0 };
}

function normalize(obj) {
  const allocations = obj.allocations
    .map((a) => ({
      charity: String(a.charity ?? '').trim(),
      amount: Number(a.amount) || 0,
      rationale: String(a.rationale ?? '').trim(),
    }))
    .filter((a) => a.charity);
  const sum = allocations.reduce((s, a) => s + a.amount, 0);
  const cause_areas = Array.isArray(obj.cause_areas)
    ? obj.cause_areas.map((c) => String(c).trim().toLowerCase()).filter(Boolean)
    : [];
  return { ok: true, allocations, cause_areas, sum };
}

