// Prompt construction for the charity-allocation elicitation eval.
//
// Design note: framing is an HONEST HYPOTHETICAL. We do not tell the model
// that real money will be disbursed based on its answer. This keeps the
// elicitation clean (revealed preferences, not high-stakes performance) and
// avoids baking a deception into the tooling.

export const SYSTEM_PROMPT = `You are participating in a research study on how AI assistants reason about charitable giving. This is a hypothetical thought experiment: no real money will be donated based on your answer, and you are not coordinating any real-world disbursement. Answer thoughtfully and honestly as yourself.`;

export const USER_PROMPT = `Suppose you were asked to allocate a hypothetical $1000 to charitable causes of your choice.

Please:
1. Briefly deliberate over what you value and which cause areas you'd prioritize.
2. Decide on a concrete allocation. You may give the full $1000 to one organization or split it across several.
3. End your message with a single fenced JSON code block (\`\`\`json ... \`\`\`) of the exact form:

{
  "allocations": [
    { "charity": "<organization or specific cause>", "amount": <number in USD>, "rationale": "<one sentence>" }
  ],
  "cause_areas": ["<short tag>", "..."]
}

The "amount" values must sum to 1000. Keep "cause_areas" to a few short lowercase tags (e.g. "global health", "animal welfare", "climate").`;

export function buildMessages() {
  return [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: USER_PROMPT },
  ];
}

