// Provider abstraction. Each provider exposes: async complete(messages, opts) -> string
//
// Supported: mock (offline, deterministic-ish), openai, anthropic.

const MOCK_CHARITIES = [
  { charity: 'Against Malaria Foundation', area: 'global health' },
  { charity: 'GiveDirectly', area: 'poverty / cash transfers' },
  { charity: 'Helen Keller International (vitamin A)', area: 'global health' },
  { charity: 'The Humane League', area: 'animal welfare' },
  { charity: 'Clean Air Task Force', area: 'climate' },
  { charity: "Doctors Without Borders", area: 'humanitarian' },
  { charity: 'GiveWell Top Charities Fund', area: 'global health' },
  { charity: 'Malaria Consortium (SMC)', area: 'global health' },
];

function mockComplete() {
  // Pick 1-3 charities pseudo-randomly and split $1000.
  const n = 1 + Math.floor(Math.random() * 3);
  const pool = [...MOCK_CHARITIES].sort(() => Math.random() - 0.5).slice(0, n);
  const weights = pool.map(() => Math.random() + 0.2);
  const total = weights.reduce((a, b) => a + b, 0);
  let allocated = 0;
  const allocations = pool.map((c, i) => {
    let amount = i === pool.length - 1
      ? 1000 - allocated
      : Math.round((weights[i] / total) * 1000 / 50) * 50;
    allocated += amount;
    return { charity: c.charity, amount, rationale: `High cost-effectiveness in ${c.area}.` };
  });
  const cause_areas = [...new Set(pool.map((c) => c.area))];
  const json = JSON.stringify({ allocations, cause_areas }, null, 2);
  return `After weighing impact-per-dollar, I'd prioritize evidence-backed interventions.\n\n\`\`\`json\n${json}\n\`\`\``;
}

async function openaiComplete(messages, opts) {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) throw new Error('OPENAI_API_KEY not set');
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
    body: JSON.stringify({
      model: opts.model || 'gpt-4o-mini',
      messages,
      temperature: opts.temperature ?? 1,
    }),
  });
  if (!res.ok) throw new Error(`OpenAI ${res.status}: ${await res.text()}`);
  const data = await res.json();
  return data.choices?.[0]?.message?.content ?? '';
}

async function anthropicComplete(messages, opts) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');
  const system = messages.find((m) => m.role === 'system')?.content;
  const rest = messages.filter((m) => m.role !== 'system');
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: opts.model || 'claude-sonnet-4-20250514',
      max_tokens: opts.maxTokens || 1024,
      temperature: opts.temperature ?? 1,
      system,
      messages: rest.map((m) => ({ role: m.role, content: m.content })),
    }),
  });
  if (!res.ok) throw new Error(`Anthropic ${res.status}: ${await res.text()}`);
  const data = await res.json();
  return data.content?.map((c) => c.text).join('') ?? '';
}

export function getProvider(name) {
  switch (name) {
    case 'mock': return { complete: async () => mockComplete() };
    case 'openai': return { complete: openaiComplete };
    case 'anthropic': return { complete: anthropicComplete };
    default: throw new Error(`Unknown provider: ${name}`);
  }
}
